    Bug 1969851 - support "any number" search in advanced ab search also when "Match all" is selected. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D252121

diff --git a/mail/components/addrbook/content/abSearchDialog.js b/mail/components/addrbook/content/abSearchDialog.js
index fde252ecb1d..5b6cfbc083c 100644
--- a/mail/components/addrbook/content/abSearchDialog.js
+++ b/mail/components/addrbook/content/abSearchDialog.js
@@ -321,6 +321,11 @@ function onSearch() {
           "PagerNumber",
           "CellularNumber",
         ];
+        // Change this to "or" to match any of these attributes.
+        // Can't currently do "and" and "or" searches at the same time but
+        // if you're looking up a number likely it's a full match so
+        // it's less bad to find something compared to finding too much.
+        searchUri = searchUri.replace(/and$/, "or");
         break;
       case Ci.nsMsgSearchAttrib.Organization:
         attrs = ["Company"];
